-- Paket ABT "abt-relaas-penetapan-30okt" (30 Okt 2026): relaas/pemberitahuan dan penetapan PTSP blangko Derry - koma tunggal, spasi, identitas, upaya hukum pemberitahuan putusan, tanggal relaas e-Court, PA tujuan delegasi, penetapan hari sidang.
-- PERIKSA (baca saja): tiap baris persis isi paket. Baris terakhir harus: SEMUA COCOK
SELECT label, ok FROM (
SELECT 'variabel 11200' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11200 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = '715bcc621768faf3aa733e2ddf6bdb94') AS ok
UNION ALL SELECT 'variabel 11201' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11201 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = 'e9e4bc4014c3eee53849241b91a4591b') AS ok
