UNION ALL SELECT 'variabel 11206' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11206 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = '439a69c4c58cb3647ec81774199d018d') AS ok
UNION ALL SELECT 'variabel 11207' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11207 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = 'e19377daca46f8d06aa3fc653fa46471') AS ok
