UNION ALL SELECT 'variabel 11209' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11209 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = 'ae798ab94decb1fd6c8d820ba51de337') AS ok
UNION ALL SELECT 'variabel 11210' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11210 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = 'c16e7b9e46b121d5f4b28c8c2bef96f9') AS ok
