UNION ALL SELECT 'variabel 11213' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11213 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = '440ba4719bdd65b90a804ed942fbba39') AS ok
UNION ALL SELECT 'variabel 11214' AS label, (SELECT COUNT(*) FROM aps_badilag.abt_variabel v WHERE v.no_var = 11214 AND MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked)) = '9a70427a3c38e6f9e65c6b11ef635710') AS ok
