UNION ALL SELECT IF((SELECT COUNT(*) FROM aps_badilag.abt_variabel v JOIN (SELECT 11200 AS n, '715bcc621768faf3aa733e2ddf6bdb94' AS h UNION ALL SELECT 11201 AS n, 'e9e4bc4014c3eee53849241b91a4591b' AS h UNION ALL SELECT 11202 AS n, 'ebd52d5b729c534a64063d6728f741ce' AS h UNION ALL SELECT 11203 AS n, '45623fb156d860dab075323e2211a6c7' AS h UNION ALL SELECT 11204 AS n, 'c3a21c1d68433ff59ae561c5b2412e99' AS h UNION ALL SELECT 11205 AS n, '8ad7b769e3c00be2873bfe93e7057647' AS h UNION ALL SELECT 11206 AS n, '439a69c4c58cb3647ec81774199d018d' AS h UNION ALL SELECT 11207 AS n, 'e19377daca46f8d06aa3fc653fa46471' AS h UNION ALL SELECT 11208 AS n, '828d478920e26ed32b80c466b89fc439' AS h UNION ALL SELECT 11209 AS n, 'ae798ab94decb1fd6c8d820ba51de337' AS h UNION ALL SELECT 11210 AS n, 'c16e7b9e46b121d5f4b28c8c2bef96f9' AS h UNION ALL SELECT 11211 AS n, 'c08e4af2f0dffb04b6bb5e2d4929f383' AS h UNION ALL SELECT 11212 AS n, '680f5dbc927ebfb38f8b3aee639b7767' AS h UNION ALL SELECT 11213 AS n, '440ba4719bdd65b90a804ed942fbba39' AS h UNION ALL SELECT 11214 AS n, '9a70427a3c38e6f9e65c6b11ef635710' AS h) x ON x.n = v.no_var AND x.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), v.locked))) = 15, 'SEMUA COCOK', 'TIDAK COCOK'), 1;
